.frequency-panel{padding-top:27px}.section-heading{display:flex;align-items:flex-end;justify-content:space-between;margin-bottom:13px}.section-heading h2,.archive-header h2{font:500 19px var(--display);letter-spacing:-.4px;margin-top:5px}.frequency-hint{font:9px var(--mono);color:#748399;margin-bottom:3px}.frequency-list{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.frequency-card{position:relative;text-align:left;background:#101826;border:1px solid #263244;padding:11px 12px 10px 43px;min-height:70px;color:#dce7e9;cursor:pointer;transition:border-color .2s,background .2s}.frequency-card:hover{border-color:#657b88}.frequency-card.active{background:#15252c;border-color:#78cdbd;box-shadow:inset 0 0 0 1px #78cdbd20}.freq-icon{position:absolute;left:13px;top:13px;font-size:19px;color:var(--gold)}.frequency-card:nth-child(2) .freq-icon{color:#8fbded}.frequency-card:nth-child(3) .freq-icon{color:#c5a5ed}.freq-name,.freq-desc,.freq-bonus{display:block}.freq-name{font:10px var(--mono);letter-spacing:1px}.freq-desc{font-size:9px;color:#78899a;margin-top:4px}.freq-bonus{font:8px var(--mono);color:var(--cyan);position:absolute;right:9px;bottom:9px}.sky-status{display:flex;gap:8px;align-items:center;margin-top:11px;font:8px var(--mono);letter-spacing:1px;color:#a9b5bf}.sky-pip{width:5px;height:5px}.sky-timer{margin-left:auto;color:#718197}.side-column{display:flex;flex-direction:column;gap:13px}.story-card,.upgrade-panel,.mission-card,.archive-card{border:1px solid #283343;background:#111a28}.story-card{padding:16px 18px 13px;background:linear-gradient(112deg,#19242e,#121b28 68%);position:relative;overflow:hidden}.story-card:after{content:'“';position:absolute;right:18px;top:0;font:100px Georgia;color:#d0bb8720}.story-top,.story-foot{display:flex;align-items:center;justify-content:space-between;position:relative;z-index:1}.story-star{color:var(--gold);font-size:13px}.story-card p{font:500 15px/1.5 var(--display);color:#dce3e2;margin:13px 22px 12px 0;min-height:45px;position:relative;z-index:1}.story-foot{font:8px var(--mono);letter-spacing:.8px;color:#8493a3}.signal-bars{height:11px;display:flex;gap:2px;align-items:flex-end}.signal-bars i{display:block;width:2px;background:#a6d9cd;height:4px;opacity:.7}.signal-bars i:nth-child(2){height:8px}.signal-bars i:nth-child(3){height:5px}.signal-bars i:nth-child(4){height:10px}.signal-bars i:nth-child(5){height:6px}.upgrade-panel{padding:17px 17px 13px}.upgrade-heading{margin-bottom:13px}.upgrade-heading h2{font-size:18px}.upgrade-count{font:8px var(--mono);color:#76869a;letter-spacing:.7px;margin-bottom:4px}.upgrade-list{display:flex;flex-direction:column;gap:7px}.upgrade-row{display:grid;grid-template-columns:37px minmax(0,1fr) auto;align-items:center;gap:10px;border:1px solid #263243;background:#0e1622;min-height:62px;padding:8px 10px;transition:border-color .2s,opacity .2s}.upgrade-row.affordable{border-color:#526b69}.upgrade-row.locked{opacity:.57}.upgrade-icon{width:34px;height:34px;display:grid;place-items:center;background:#1a2934;border:1px solid #314550;color:#a9ded5;font-size:17px}.upgrade-row:nth-child(2) .upgrade-icon{color:#d8b786;background:#29251f;border-color:#514633}.upgrade-row:nth-child(3) .upgrade-icon{color:#b4a4e7;background:#242239;border-color:#413957}.upgrade-info{min-width:0}.upgrade-name{font:500 11px var(--display);color:#e1e9e9}.upgrade-desc{font:8px var(--mono);color:#7d8b9b;margin-top:4px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.upgrade-owned{font:8px var(--mono);color:#8999a8;margin-top:4px}.buy-button{background:#19262d;border:1px solid #34494b;color:#bee8dc;padding:7px 8px;min-width:69px;cursor:pointer;font:9px var(--mono);transition:all .15s}.buy-button:hover:not(:disabled){background:#23413d;border-color:#8de5d3;color:#edfff8}.buy-button:disabled{color:#647282;border-color:#293542;background:#141d29;cursor:not-allowed}.buy-cost{display:block;font-size:8px;color:#899a9d;margin-top:3px}.mission-card{display:flex;align-items:center;gap:12px;padding:13px 14px;background:#151d29}.mission-icon{width:34px;height:34px;flex-shrink:0;border:1px solid #65553d;background:#2c271f;display:grid;place-items:center;color:var(--gold);font-size:18px}.mission-content{min-width:0;flex:1}.mission-content strong{display:block;font:500 11px var(--display);margin-top:5px}.mission-content>span:not(.eyebrow){display:block;font-size:9px;color:#8291a1;margin-top:3px}.mission-progress{display:flex;align-items:center;gap:8px;margin-top:8px}.mission-track{width:68px;height:2px}.mission-track span{background:var(--gold)}.mission-progress>span{font:8px var(--mono);color:#8493a1}.mission-reward{font:9px var(--mono);color:#e3c18c;align-self:flex-end;margin-bottom:3px;white-space:nowrap}.mission-reward b{font-weight:500}.archive-card{padding:16px 17px 13px}.archive-header{display:flex;align-items:center;justify-content:space-between}.archive-header h2{font-size:17px}.echo-count{font:14px var(--display);color:#d6c38d;display:flex;gap:6px;align-items:center}.echo-count span{font-size:19px}.echo-list{min-height:38px;display:flex;align-items:center;gap:6px;flex-wrap:wrap;padding:9px 0 7px}.empty-echo{font:9px var(--mono);color:#78889a}.echo-token{font:9px var(--mono);color:#dfcfaa;background:#25251f;border:1px solid #524a38;padding:5px 7px}.transmit-button{border:1px solid #344143;background:#172225;color:#c5e8df;width:100%;height:34px;display:flex;align-items:center;justify-content:center;gap:7px;font:8px var(--mono);letter-spacing:.7px;cursor:pointer;transition:all .2s}.transmit-button:hover:not(:disabled){background:#24403d;border-color:var(--cyan)}.transmit-button:disabled{opacity:.56;cursor:not-allowed}.transmit-button>span:first-child{color:var(--gold);font-size:12px}.transmit-cost{color:#859497;margin-left:4px}.transmit-button.ready{box-shadow:0 0 15px #8ce3d51d;border-color:#92d8c8}.app-shell footer{height:53px;border-top:1px solid #202938;display:flex;align-items:center;justify-content:space-between;font:8px var(--mono);letter-spacing:1px;color:#788899}.app-shell footer>div{display:flex;align-items:center;gap:22px}.save-indicator{display:flex;align-items:center;gap:6px;color:#83969a}.save-indicator i{width:5px;height:5px;border-radius:50%;background:#7fceb7;box-shadow:0 0 6px #7fceb7}.reset-button{background:none;border:0;color:#6b798a;font:8px var(--mono);letter-spacing:1px;cursor:pointer}.reset-button:hover{color:#d6a39d}.toast{position:fixed;left:50%;bottom:22px;z-index:10;transform:translate(-50%,20px);padding:11px 17px;background:#e4f3e9;color:#152720;font:11px var(--mono);box-shadow:0 8px 30px #0008;opacity:0;pointer-events:none;transition:all .25s}.toast.show{opacity:1;transform:translate(-50%,0)}.modal-backdrop{position:fixed;inset:0;background:#050912d9;z-index:20;display:none;align-items:center;justify-content:center;padding:20px;backdrop-filter:blur(8px)}.modal-backdrop.open{display:flex}.modal{position:relative;width:min(410px,100%);padding:34px 32px 27px;background:#111b28;border:1px solid #344556;text-align:center;box-shadow:0 22px 90px #000a}.modal-close{position:absolute;right:13px;top:11px;background:none;border:0;color:#8694a3;font-size:22px;cursor:pointer}.modal-symbol{display:block;font-size:31px;color:var(--cyan);margin-bottom:13px;text-shadow:0 0 20px #90e7d866}.modal h2{font:500 25px var(--display);margin:10px 0}.modal>p{font-size:12px;line-height:1.6;color:#9aa8b7;margin:12px 0 18px}.modal-echo{border:1px solid #464638;background:#201f1b;padding:12px;display:flex;justify-content:center;align-items:center;gap:8px;margin-bottom:17px;color:#e3c989}.modal-echo>span{font-size:18px}.modal-echo strong{font:12px var(--mono)}.modal-echo small{font:8px var(--mono);color:#9e987d}.modal-confirm{width:100%;height:40px;background:#8be0cf;border:0;color:#10221f;font:10px var(--mono);letter-spacing:.7px;cursor:pointer}.modal-confirm:hover{background:#b4f1e4}.modal-cancel{margin-top:14px;background:none;border:0;color:#8796a5;font:10px var(--mono);cursor:pointer}.modal-cancel:hover{color:#e8f1ef}
@media(max-width:1050px){.app-shell{padding:0 28px}.game-layout{grid-template-columns:minmax(0,1.15fr) minmax(320px,.85fr);gap:18px}.resource-primary,.resource-stat,.next-goal{padding-left:12px;padding-right:12px}.resource-number{font-size:20px}.upgrade-panel{padding:14px 12px}.upgrade-desc{font-size:7px}}
@media(max-width:760px){.app-shell{padding:0 16px}.topbar{height:60px}.brand{gap:7px;font-size:11px}.brand-sub{font-size:8px}.station-status{font-size:8px}.sound-label{display:none}.game-layout{display:flex;flex-direction:column;gap:20px;padding:25px 0 20px}.intro-row{align-items:flex-end;gap:8px}.intro-copy{font-size:12px}.day-chip{min-width:110px;padding:9px}.day-chip>span:last-child{font-size:7px}.resource-strip{height:auto;min-height:76px;grid-template-columns:1.1fr .8fr .8fr}.resource-primary,.resource-stat{padding:11px 9px}.resource-primary{gap:7px}.resource-symbol{font-size:18px}.resource-label,.resource-stat span{font-size:8px}.resource-number{font-size:18px}.resource-stat strong{font-size:15px}.next-goal{grid-column:1/-1;border-top:1px solid #283343;padding:9px 12px;display:grid;grid-template-columns:auto 1fr;align-items:center;gap:7px}.next-goal .resource-label{grid-column:1/2}.next-goal strong{grid-column:2/3;grid-row:1/2;margin:0;text-align:right}.goal-track{grid-column:1/-1}.core-stage{height:300px}.moon-one{right:12%}.orbit-b{width:245px}.frequency-panel{padding-top:21px}.frequency-list{gap:5px}.frequency-card{padding:10px 7px 9px 35px;min-height:72px}.freq-icon{left:10px;font-size:17px}.freq-name{font-size:9px}.freq-desc{font-size:8px}.freq-bonus{font-size:7px;right:5px;bottom:7px}.frequency-hint{font-size:8px}.side-column{gap:11px}.story-card p{font-size:14px}.app-shell footer{height:auto;min-height:52px;gap:10px;font-size:7px}.app-shell footer>div{gap:12px}.reset-button{font-size:7px}}
@media(max-width:390px){.app-shell{padding:0 11px}.brand-sub,.brand-divider{display:none}.station-status{gap:5px}.intro-row{align-items:flex-start}.day-chip{min-width:92px}.day-chip>span:last-child{white-space:normal}.frequency-hint{max-width:95px;text-align:right;line-height:1.4}.resource-primary{padding-left:7px}.resource-number{font-size:16px}.resource-stat{padding-left:7px}.app-shell footer>span{max-width:175px;line-height:1.5}}

(() => {
  'use strict';
  const SAVE_KEY = 'afterlight-save-v1';
  const frequencies = ['warm', 'deep', 'clear'];
  const phases = [
    { name: 'WARMTH', line: 'WARMTH IS IN PHASE' },
    { name: 'DEEP SPACE', line: 'DEEP SPACE IS IN PHASE' },
    { name: 'CLEAR SKY', line: 'CLEAR SKY IS IN PHASE' }
  ];
  const upgrades = [
    { id: 'relay', name: 'Listening post', icon: '⌁', desc: 'A second ear in the dark · +0.4 drift/sec', base: 15, effect: 'rate', amount: .4, unlock: 0 },
    { id: 'choir', name: 'The night choir', icon: '♬', desc: 'Old radios singing together · +2 drift/sec', base: 90, effect: 'rate', amount: 2, unlock: 40 },
    { id: 'mirror', name: 'Moon mirror', icon: '◒', desc: 'Focus the light · +2 pulse strength', base: 240, effect: 'click', amount: 2, unlock: 150 },
    { id: 'array', name: 'Deep-space array', icon: '✧', desc: 'Listen between the stars · +12 drift/sec', base: 1100, effect: 'rate', amount: 12, unlock: 700 }
  ];
  const missions = [
    { title: 'A voice in the dark', description: 'Send 12 pulses to make the old dish hum.', type: 'pulses', target: 12, reward: 12 },
    { title: 'A second pair of ears', description: 'Build 3 listening posts for the station.', type: 'relay', target: 3, reward: 55 },
    { title: 'Keep the porch light on', description: 'Gather 250 signal. Someone may be watching.', type: 'lifetime', target: 250, reward: 90 },
    { title: 'Let the choir answer', description: 'Build 2 night choirs and fill the silence.', type: 'choir', target: 2, reward: 180 },
    { title: 'Reflect what remains', description: 'Build 2 moon mirrors to focus your pulse.', type: 'mirror', target: 2, reward: 400 },
    { title: 'A signal beyond the moon', description: 'Gather 2,000 signal. The reply is getting closer.', type: 'lifetime', target: 2000, reward: 900 },
    { title: 'The sky has a voice', description: 'Build 2 deep-space arrays. Find out who it belongs to.', type: 'array', target: 2, reward: 2200 }
  ];
  const fresh = () => ({ signal: 0, lifetime: 0, echoes: 0, upgrades: { relay: 0, choir: 0, mirror: 0, array: 0 }, pulses: 0, mission: 0, missionClaimed: 0, frequency: 'warm', phase: 0, phaseAt: Date.now(), lastSave: Date.now(), fragmentAt: 0, fragments: [], sound: false });
  let state = fresh();
  try {
    const saved = JSON.parse(localStorage.getItem(SAVE_KEY) || 'null');
    if (saved && typeof saved === 'object') {
      state = { ...fresh(), ...saved, upgrades: { ...fresh().upgrades, ...(saved.upgrades || {}) }, fragments: Array.isArray(saved.fragments) ? saved.fragments.slice(-5) : [] };
      state.signal = Math.max(0, Number(state.signal) || 0);
      state.lifetime = Math.max(state.signal, Number(state.lifetime) || 0);
      state.echoes = Math.max(0, Math.floor(Number(state.echoes) || 0));
      state.mission = Math.max(0, Math.floor(Number(state.mission) || 0));
      state.pulses = Math.max(0, Math.floor(Number(state.pulses) || 0));
      state.phase = Math.abs(Math.floor(Number(state.phase) || 0)) % 3;
      if (!frequencies.includes(state.frequency)) state.frequency = 'warm';
      Object.keys(state.upgrades).forEach(id => state.upgrades[id] = Math.max(0, Math.floor(Number(state.upgrades[id]) || 0)));
      const away = Math.min(8 * 60 * 60, Math.max(0, (Date.now() - (Number(state.lastSave) || Date.now())) / 1000));
      const drift = getBaseRate() * away;
      if (drift > 1) { state.signal += drift; state.lifetime += drift; setTimeout(() => toast(`Welcome back. ${format(drift)} signal gathered while you were away.`), 500); }
      if (Date.now() - (Number(state.phaseAt) || Date.now()) >= 60000) state.phaseAt = Date.now();
    }
  } catch (_) { state = fresh(); }

  const $ = id => document.getElementById(id);
  const amount = $('signalAmount'), rateLabel = $('rateAmount'), clickLabel = $('clickAmount');
  let toastTimer, lastTick = Date.now(), lastSave = 0;
  let soundContext;
  function getBaseRate() { return upgrades.reduce((sum, item) => sum + (item.effect === 'rate' ? state.upgrades[item.id] * item.amount : 0), 0); }
  function echoMultiplier() { return 1 + state.echoes * .2; }
  function rate() { return getBaseRate() * echoMultiplier() * (state.frequency === 'deep' && state.phase === 1 ? 1.2 : 1); }
  function clickPower() { return (1 + state.upgrades.mirror * 2) * echoMultiplier() * (state.frequency === 'warm' && state.phase === 0 ? 1.25 : 1); }
  function format(value) {
    if (!Number.isFinite(value)) return '∞';
    if (value < 1000) return (value < 10 && value % 1 ? value.toFixed(1) : Math.floor(value)).toLocaleString('en-US');
    const units = [['Qa', 1e15], ['T', 1e12], ['B', 1e9], ['M', 1e6], ['K', 1e3]];
    for (const [label, size] of units) if (value >= size) return (value / size).toFixed(value / size >= 100 ? 0 : 1) + label;
    return String(Math.floor(value));
  }
  function cost(item) { return Math.floor(item.base * Math.pow(1.17, state.upgrades[item.id])); }
  function addSignal(value) { if (!(value > 0) || !Number.isFinite(value)) return; state.signal += value; state.lifetime += value; }
  function save() { try { state.lastSave = Date.now(); localStorage.setItem(SAVE_KEY, JSON.stringify(state)); } catch (_) {} }
  function toast(message) { const el = $('toast'); el.textContent = message; el.classList.add('show'); clearTimeout(toastTimer); toastTimer = setTimeout(() => el.classList.remove('show'), 2600); }
  function playTone(freq = 440, duration = .07) {
    if (!state.sound) return;
    try { soundContext ||= new (window.AudioContext || window.webkitAudioContext)(); const osc = soundContext.createOscillator(), gain = soundContext.createGain(); osc.frequency.value = freq; osc.type = 'sine'; gain.gain.setValueAtTime(.035, soundContext.currentTime); gain.gain.exponentialRampToValueAtTime(.001, soundContext.currentTime + duration); osc.connect(gain); gain.connect(soundContext.destination); osc.start(); osc.stop(soundContext.currentTime + duration); } catch (_) {}
  }
  function activeMission() { return missions[Math.min(state.mission, missions.length - 1)]; }
  function missionProgress(m) { if (!m) return 0; if (m.type === 'pulses') return state.pulses; if (m.type === 'lifetime') return state.lifetime; return state.upgrades[m.type] || 0; }
  function renderUpgrades() {
    const list = $('upgradeList'); list.innerHTML = '';
    upgrades.forEach(item => {
      const count = state.upgrades[item.id], price = cost(item), locked = state.lifetime < item.unlock;
      const row = document.createElement('div'); row.className = `upgrade-row${!locked && state.signal >= price ? ' affordable' : ''}${locked ? ' locked' : ''}`;
      const icon = document.createElement('div'); icon.className = 'upgrade-icon'; icon.textContent = item.icon;
      const info = document.createElement('div'); info.className = 'upgrade-info';
      const name = document.createElement('div'); name.className = 'upgrade-name'; name.textContent = item.name;
      const desc = document.createElement('div'); desc.className = 'upgrade-desc'; desc.textContent = locked ? `Unlocks at ${format(item.unlock)} lifetime signal` : item.desc;
      const owned = document.createElement('div'); owned.className = 'upgrade-owned'; owned.textContent = `OWNED  ${count}`;
      info.append(name, desc, owned);
      const button = document.createElement('button'); button.className = 'buy-button'; button.disabled = locked || state.signal < price; button.innerHTML = `${locked ? 'LOCKED' : 'BUILD'}<span class="buy-cost">${locked ? format(item.unlock) : `${format(price)} ◉`}</span>`;
      button.setAttribute('aria-label', `Build ${item.name} for ${format(price)} signal`); button.addEventListener('click', () => buy(item));
      row.append(icon, info, button); list.append(row);
    });
    $('upgradeCount').textContent = `${Object.values(state.upgrades).reduce((a, b) => a + b, 0)} BUILT`;
  }
  function render() {
    amount.textContent = format(state.signal); rateLabel.textContent = format(rate()); clickLabel.textContent = format(clickPower());
    const goals = [24, 40, 150, 700, 2000, 10000, 50000, 100000];
    const goal = goals.find(g => state.lifetime < g) || 1000000;
    $('nextGoal').textContent = `${format(goal)} signal`; $('goalFill').style.width = `${Math.min(100, state.lifetime / goal * 100)}%`;
    $('cycleNumber').textContent = String(state.echoes + 1).padStart(2, '0');
    $('cycleName').textContent = state.echoes ? 'A NEW TRANSMISSION' : 'THE FIRST PING';
    $('resonanceFill').style.width = `${Math.min(100, (state.signal % 100) / 100 * 100)}%`; $('resonanceText').textContent = `${Math.floor(state.signal % 100)}%`;
    document.querySelectorAll('.frequency-card').forEach(button => button.classList.toggle('active', button.dataset.frequency === state.frequency));
    $('skyText').textContent = phases[state.phase].line;
    const seconds = Math.max(0, 60 - Math.floor((Date.now() - state.phaseAt) / 1000)); $('skyTimer').textContent = `SHIFT IN ${seconds}S`;
    const mission = activeMission();
    if (mission) {
      $('missionNumber').textContent = String(state.mission + 1).padStart(2, '0'); $('missionTitle').textContent = mission.title; $('missionDescription').textContent = mission.description;
      $('missionReward').textContent = format(mission.reward); $('missionProgress').textContent = `${format(Math.min(missionProgress(mission), mission.target))} / ${format(mission.target)}`;
      $('missionFill').style.width = `${Math.min(100, missionProgress(mission) / mission.target * 100)}%`;
    } else { $('missionTitle').textContent = 'The station is yours'; $('missionDescription').textContent = 'Keep the signal alive. There is always more to hear.'; $('missionProgress').textContent = 'COMPLETE'; $('missionFill').style.width = '100%'; }
    $('echoCount').textContent = state.echoes; $('echoList').innerHTML = '';
    if (!state.fragments.length) { const empty = document.createElement('span'); empty.className = 'empty-echo'; empty.textContent = 'Your first echo is waiting in the noise.'; $('echoList').append(empty); }
    state.fragments.slice().reverse().forEach(fragment => { const chip = document.createElement('span'); chip.className = 'echo-token'; chip.textContent = `✧ ${fragment}`; $('echoList').append(chip); });
    const transmit = $('transmitButton'), canTransmit = state.signal >= 100000;
    transmit.disabled = !canTransmit; transmit.classList.toggle('ready', canTransmit);
    transmit.querySelector('.transmit-cost').textContent = canTransmit ? `${Math.max(1, Math.floor(state.signal / 100000))} ECHO${state.signal >= 200000 ? 'ES' : ''} AVAILABLE` : `${format(100000 - state.signal)} SIGNAL TO GO`;
    $('soundButton').innerHTML = `♫<span class="sound-label">SOUND ${state.sound ? 'ON' : 'OFF'}</span>`;
    renderUpgrades(); checkMission();
  }
  function checkMission() {
    const mission = activeMission(); if (!mission || missionProgress(mission) < mission.target || state.missionClaimed === state.mission) return;
    state.missionClaimed = state.mission; addSignal(mission.reward); toast(`Field note complete: +${format(mission.reward)} signal`); playTone(680, .18);
    state.mission++; state.missionClaimed = -1;
  }

  const voiceLines = [
    '“I used to leave the porch light on. Just in case.”',
    '“There are still stars over the water. I checked.”',
    '“If you can hear this, the garden is growing wild.”',
    '“I saved you a seat by the window.”',
    '“Tell the moon we said hello.”',
    '“We kept the radio on for you.”',
    '“The quiet was never empty. Not really.”'
  ];
  function updateVoice() {
    const index = Math.min(voiceLines.length - 1, state.fragments.length);
    $('storyText').textContent = voiceLines[index];
    $('story-card');
    const eyebrow = document.querySelector('.story-card .eyebrow');
    if (eyebrow) eyebrow.textContent = `INCOMING · FRAGMENT ${String(index + 1).padStart(2, '0')}`;
  }
  function buy(item) {
    const price = cost(item);
    if (state.lifetime < item.unlock || state.signal < price) return;
    state.signal -= price; state.upgrades[item.id]++;
    playTone(310 + state.upgrades[item.id] * 16, .1);
    toast(`${item.name} is listening now.`); render(); save();
  }
  function pulse() {
    const gain = clickPower(); addSignal(gain); state.pulses++;
    const stage = $('coreStage'); stage.classList.remove('pulsing'); void stage.offsetWidth; stage.classList.add('pulsing');
    const button = $('pulseButton'), rect = button.getBoundingClientRect();
    const pop = document.createElement('span'); pop.className = 'pulse-pop'; pop.textContent = `+${format(gain)}`;
    pop.style.left = `${rect.left + rect.width / 2}px`; pop.style.top = `${rect.top + 10}px`; document.body.append(pop); setTimeout(() => pop.remove(), 950);
    playTone(state.frequency === 'clear' ? 600 : state.frequency === 'deep' ? 240 : 420, .09);
    if (state.frequency === 'clear' && state.phase === 2 && Math.random() < .045 && state.fragments.length < 5) {
      const available = ['a blue thread', 'the smell of rain', 'someone humming', 'a window left open', 'the color of home'];
      const memory = available.find(item => !state.fragments.includes(item));
