6:     { name: 'WARMTH', line: 'WARMTH IS IN PHASE' },
7:     { name: 'DEEP SPACE', line: 'DEEP SPACE IS IN PHASE' },
8:     { name: 'CLEAR SKY', line: 'CLEAR SKY IS IN PHASE' }
9:   ];
